using Ginecologia.Modules.ConsultaMedica.Domain;
using Microsoft.EntityFrameworkCore;
namespace Ginecologia.Modules.ConsultaMedica.Infrastructure;
public sealed class ConsultaMedicaDbContext(DbContextOptions<ConsultaMedicaDbContext> options) : DbContext(options)
{ public DbSet<Consulta> Consultas => Set<Consulta>(); public DbSet<PrescriptionItem> PrescriptionItems => Set<PrescriptionItem>(); public DbSet<ConsultaAttachment> ConsultaAttachments => Set<ConsultaAttachment>(); protected override void OnModelCreating(ModelBuilder b) { b.HasDefaultSchema("consulta_medica"); var c=b.Entity<Consulta>();c.ToTable("consultas");c.HasKey(x=>x.Id);foreach(var p in new[]{"Id","PatientId","RegistradoPorId"})c.Property(typeof(Guid),p).HasColumnName(ToSnake(p)); c.Property(x=>x.Fecha).HasColumnName("fecha").HasColumnType("date");c.Property(x=>x.Estado).HasColumnName("estado").HasConversion<string>().HasMaxLength(20);c.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");c.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");c.Property(x=>x.FinalizadaAtUtc).HasColumnName("finalizada_at_utc");c.Property(x=>x.PresionSistolica).HasColumnName("presion_sistolica");c.Property(x=>x.PresionDiastolica).HasColumnName("presion_diastolica");c.Property(x=>x.PesoKg).HasColumnName("peso_kg").HasPrecision(8,2);c.Property(x=>x.TallaCm).HasColumnName("talla_cm").HasPrecision(8,2);c.Property(x=>x.Fum).HasColumnName("fum").HasColumnType("date"); MapText(c,"MotivoConsulta",500);MapText(c,"PadecimientoActual",8000);MapText(c,"HallazgosMamas",2000);MapText(c,"HallazgosCervixGenitales",2000);MapText(c,"HallazgosTactoBimanual",2000);c.Property(x=>x.UltrasonidoEndometrioMm).HasColumnName("ultrasonido_endometrio_mm").HasPrecision(8,2);MapText(c,"UltrasonidoOvarioDerecho",1000);MapText(c,"UltrasonidoOvarioIzquierdo",1000);MapText(c,"UltrasonidoSacoGestacionalEmbrion",1000);MapText(c,"DiagnosticoCie",10);MapText(c,"DiagnosticoDescripcion",2000);MapText(c,"EstudiosSolicitados",2000);MapText(c,"IndicacionesProximaCita",2000);c.HasIndex(x=>new{x.PatientId,x.Fecha}).HasDatabaseName("ix_consultas_patient_fecha"); var i=b.Entity<PrescriptionItem>();i.ToTable("prescription_items");i.HasKey(x=>x.Id);i.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();i.Property(x=>x.ConsultaId).HasColumnName("consulta_id");i.Property(x=>x.Orden).HasColumnName("orden");MapText(i,"Medicamento",200);MapText(i,"Dosis",100);MapText(i,"Via",50);MapText(i,"Frecuencia",100);MapText(i,"DuracionTexto",100);c.HasMany(x=>x.PrescriptionItems).WithOne().HasForeignKey(x=>x.ConsultaId).OnDelete(DeleteBehavior.Cascade); var a=b.Entity<ConsultaAttachment>();a.ToTable("consulta_attachments");a.HasKey(x=>x.Id);a.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();a.Property(x=>x.ConsultaId).HasColumnName("consulta_id");a.Property(x=>x.NombreArchivo).HasColumnName("nombre_archivo").HasMaxLength(260);a.Property(x=>x.TipoContenido).HasColumnName("tipo_contenido").HasMaxLength(100);a.Property(x=>x.Contenido).HasColumnName("contenido").HasColumnType("bytea");a.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");c.HasMany(x=>x.Attachments).WithOne().HasForeignKey(x=>x.ConsultaId).OnDelete(DeleteBehavior.Cascade); }
private static void MapText<TEntity>(Microsoft.EntityFrameworkCore.Metadata.Builders.EntityTypeBuilder<TEntity> e,string property,int max) where TEntity:class => e.Property(property).HasColumnName(ToSnake(property)).HasMaxLength(max);
private static string ToSnake(string value) => System.Text.RegularExpressions.Regex.Replace(value,"(?<!^)([A-Z])","_$1").ToLowerInvariant(); }
